import React, { useState, useEffect, useCallback, useMemo } from 'react';
import MoviesList from './components/MoviesList';
import './App.css';

function App() {
  const [movies, setMovies] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isRetrying, setIsRetrying] = useState(false);
  const [intervalId, setIntervalId] = useState(null);
  const [newMovie, setNewMovie] = useState({
    title: '',
    openingText: '',
    releaseDate: ''
  });

  // Fetch movies from the API
  const fetchMoviesHandler = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('https://swapi.py4e.com/api/films/');
      if (!response.ok) {
        throw new Error('Something went wrong... Retrying');
      }

      const data = await response.json();

      const transformedMovies = data.results.map((movieData) => ({
        id: movieData.episode_id,
        title: movieData.title,
        openingText: movieData.opening_crawl,
        releaseDate: movieData.release_date,
      }));

      setMovies(transformedMovies);
      setIsRetrying(false);

      if (intervalId) {
        clearInterval(intervalId);
        setIntervalId(null);
      }
    } catch (err) {
      setError('Something went wrong... Retrying');

      if (!intervalId) {
        setIsRetrying(true);
        const id = setInterval(fetchMoviesHandler, 5000);
        setIntervalId(id);
      }
    }

    setIsLoading(false);
  }, [intervalId]);

  const cancelRetryHandler = useCallback(() => {
    if (intervalId) {
      clearInterval(intervalId);
      setIntervalId(null);
    }
    setIsRetrying(false);
    setError('Retry cancelled by user.');
  }, [intervalId]);

  useEffect(() => {
    fetchMoviesHandler();
  }, [fetchMoviesHandler]);

  useEffect(() => {
    return () => {
      if (intervalId) {
        clearInterval(intervalId);
      }
    };
  }, [intervalId]);

  const memoizedMoviesList = useMemo(() => {
    return movies.length > 0 ? <MoviesList movies={movies} /> : null;
  }, [movies]);

  // Handle input change for adding new movie
  const inputChangeHandler = (e) => {
    const { name, value } = e.target;
    setNewMovie((prevMovie) => ({
      ...prevMovie,
      [name]: value
    }));
  };

  // Handle adding a new movie
  const addMovieHandler = () => {
    console.log("New Movie Object:", newMovie);
    // Reset form fields after logging
    setNewMovie({
      title: '',
      openingText: '',
      releaseDate: ''
    });
  };

  return (
    <React.Fragment>
      <section>
        {/* Add Movie Form */}
        <div className="add-movie-form">
          <input
            type="text"
            name="title"
            value={newMovie.title}
            onChange={inputChangeHandler}
            placeholder="Movie Title"
          />
          <input
            type="text"
            name="openingText"
            value={newMovie.openingText}
            onChange={inputChangeHandler}
            placeholder="Opening Text"
          />
          <input
            type="date"
            name="releaseDate"
            value={newMovie.releaseDate}
            onChange={inputChangeHandler}
          />
          <button onClick={addMovieHandler}>Add Movie</button>
        </div>

        {/* Fetch Movies Button */}
        <button onClick={fetchMoviesHandler}>Fetch Movies</button>
        {isRetrying && <button onClick={cancelRetryHandler}>Cancel Retry</button>}
      </section>

      <section>
        {isLoading && <p>Loading...</p>}
        {!isLoading && error && <p>{error}</p>}
        {!isLoading && memoizedMoviesList}
        {!isLoading && movies.length === 0 && !error && <p>No movies found.</p>}
      </section>
    </React.Fragment>
  );
}

export default App;
